func (this *Tokocrypto) Nonce() int64 {
	return this.Milliseconds() - *this.SafeInteger(this.Options, "timeDifference", 0)
}

/**
 * @method
 * @name tokocrypto#fetchTime
 * @see https://www.tokocrypto.com/apidocs/#check-server-time
 * @description fetches the current integer timestamp in milliseconds from the exchange server
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {int} the current integer timestamp in milliseconds from the exchange server
 */
func (this *Tokocrypto) FetchTimeAsync(optionalArgs ...any) <-chan AsyncResult[*int64] {
	ch := make(chan AsyncResult[*int64], 1)
	go this.fetchTimeBody(ch, optionalArgs...)
	return ch
}
func (this *Tokocrypto) fetchTimeBody(ch chan AsyncResult[*int64], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params

	r := <-this.PublicGetOpenV1CommonTime(params)
	if r.Err != nil {
		panic(r.Err)
	}
	var response map[string]any = r.Value

	//
	// {
	//     "code": 0,
	//     "msg": "Success",
	//     "data": null,
	//     "timestamp": 1737378074159
	// }
	//
	ch <- AsyncResult[*int64]{Value: this.SafeInteger(response, "timestamp")}
	return nil
}

/**
 * @method
 * @name tokocrypto#fetchMarkets
 * @see https://www.tokocrypto.com/apidocs/#get-all-supported-trading-symbol
 * @description retrieves data on all markets for tokocrypto
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object[]} an array of objects representing market data
 */
func (this *Tokocrypto) FetchMarketsAsync(optionalArgs ...any) <-chan AsyncResult[[]MarketInterface] {
	ch := make(chan AsyncResult[[]MarketInterface], 1)
	go this.fetchMarketsBody(ch, optionalArgs...)
	return ch
}
func (this *Tokocrypto) fetchMarketsBody(ch chan AsyncResult[[]MarketInterface], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params

	r := <-this.PublicGetOpenV1CommonSymbols(params)
	if r.Err != nil {
		panic(r.Err)
	}
	var response map[string]any = r.Value
	//
	//     {
	//         "code":0,
	//         "msg":"Success",
	//         "data":{
	//             "list":[
	//                 {
	//                     "type":1,
	//                     "symbol":"1INCH_BTC",
	//                     "baseAsset":"1INCH",
	//                     "basePrecision":8,
	//                     "quoteAsset":"BTC",
	//                     "quotePrecision":8,
	//                     "filters":[
	//                         {"filterType":"PRICE_FILTER","minPrice":"0.00000001","maxPrice":"1000.00000000","tickSize":"0.00000001","applyToMarket":false},
	//                         {"filterType":"PERCENT_PRICE","multiplierUp":5,"multiplierDown":0.2,"avgPriceMins":"5","applyToMarket":false},
	//                         {"filterType":"LOT_SIZE","minQty":"0.10000000","maxQty":"90000000.00000000","stepSize":"0.10000000","applyToMarket":false},
	//                         {"filterType":"MIN_NOTIONAL","avgPriceMins":"5","minNotional":"0.00010000","applyToMarket":true},
	//                         {"filterType":"ICEBERG_PARTS","applyToMarket":false,"limit":"10"},
	//                         {"filterType":"MARKET_LOT_SIZE","minQty":"0.00000000","maxQty":"79460.14117231","stepSize":"0.00000000","applyToMarket":false},
	//                         {"filterType":"TRAILING_DELTA","applyToMarket":false},
	//                         {"filterType":"MAX_NUM_ORDERS","applyToMarket":false},
	//                         {"filterType":"MAX_NUM_ALGO_ORDERS","applyToMarket":false,"maxNumAlgoOrders":"5"}
	//                     ],
	//                     "orderTypes":["LIMIT","LIMIT_MAKER","MARKET","STOP_LOSS_LIMIT","TAKE_PROFIT_LIMIT"],
	//                     "icebergEnable":1,
	//                     "ocoEnable":1,
	//                     "spotTradingEnable":1,
	//                     "marginTradingEnable":1,
	//                     "permissions":["SPOT","MARGIN"]
	//                 },
	//             ]
	//         },
	//         "timestamp":1659492212507
	//     }
	//
	if *this.SafeBool(this.Options, "adjustForTimeDifference", false) {

		r1 := <-this.LoadTimeDifferenceAsync()
		if r1.Err != nil {
			panic(r1.Err)
		}
	}
	var data map[string]any = SafeMapTyped(response, "data")
	var list []any = SafeListTyped(data, "list")
	var result []any = []any{}
	for i := 0; i < len(list); i++ {
		var market any = DerefScalar(list[i])
		var baseId *string = this.SafeString(market, "baseAsset")
		var quoteId *string = this.SafeString(market, "quoteAsset")
		var id *string = this.SafeString(market, "symbol")
		var lowercaseId *string = this.SafeStringLower(market, "symbol")
		var settleId *string = this.SafeString(market, "marginAsset")
		var base *string = this.SafeCurrencyCode(baseId)
		var quote *string = this.SafeCurrencyCode(quoteId)
		if (base == nil) || (quote == nil) {
			continue
		}
		var settle *string = this.SafeCurrencyCode(settleId)
		var symbol string = *base + "/" + *quote
		var filters []any = SafeListTyped(market, "filters")
		var filtersByType map[string]any = this.IndexBy(filters, "filterType")
		var status *string = this.SafeString(market, "spotTradingEnable")
		var active bool = (status != nil && *status == "1")
		var permissions []any = SafeListTyped(market, "permissions")
		for j := 0; j < len(permissions); j++ {
			if this.SafeString(permissions, j) != nil && *this.SafeString(permissions, j) == "TRD_GRP_003" {
				active = false
				break
			}
		}
		var marginTradingEnable *string = this.SafeString(market, "marginTradingEnable")
		var costMin *float64 = nil
		var precision map[string]any = map[string]any{
			"amount": this.ParseNumber(this.ParsePrecision(this.SafeString(market, "quantityPrecision"))),
			"price":  this.ParseNumber(this.ParsePrecision(this.SafeString(market, "pricePrecision"))),
			"base":   this.ParseNumber(this.ParsePrecision(this.SafeString(market, "basePrecision"))),
			"quote":  this.ParseNumber(this.ParsePrecision(this.SafeString(market, "quotePrecision"))),
		}
		var limits map[string]any = map[string]any{
			"leverage": map[string]any{
				"min": nil,
				"max": nil,
			},
			"amount": map[string]any{
				"min": nil,
				"max": nil,
			},
			"price": map[string]any{
				"min": nil,
				"max": nil,
			},
			"cost": map[string]any{
				"min": costMin,
				"max": nil,
			},
		}
		if _, ok := filtersByType["PRICE_FILTER"]; ok {
			var filter map[string]any = SafeMapTyped(filtersByType, "PRICE_FILTER")
			// PRICE_FILTER reports zero values for maxPrice
			// since they updated filter types in November 2018
			// https://github.com/ccxt/ccxt/issues/4286
			// therefore limits['price']['max'] doesn't have any meaningful value except undefined
			limits["price"] = map[string]any{
				"min": this.SafeNumber(filter, "minPrice"),
				"max": this.SafeNumber(filter, "maxPrice"),
			}
			precision["price"] = filter["tickSize"]
		}
		if _, ok := filtersByType["LOT_SIZE"]; ok {
			var filter map[string]any = SafeMapTyped(filtersByType, "LOT_SIZE")
			precision["amount"] = this.SafeNumber(filter, "stepSize")
			limits["amount"] = map[string]any{
				"min": this.SafeNumber(filter, "minQty"),
				"max": this.SafeNumber(filter, "maxQty"),
			}
		}
		if _, ok := filtersByType["MARKET_LOT_SIZE"]; ok {
			var filter map[string]any = SafeMapTyped(filtersByType, "MARKET_LOT_SIZE")
			limits["market"] = map[string]any{
				"min": this.SafeNumber(filter, "minQty"),
				"max": this.SafeNumber(filter, "maxQty"),
			}
		}
		var entry map[string]any = map[string]any{
			"id":             id,
			"lowercaseId":    lowercaseId,
			"symbol":         symbol,
			"base":           base,
			"quote":          quote,
			"settle":         settle,
			"baseId":         baseId,
			"quoteId":        quoteId,
			"settleId":       settleId,
			"type":           "spot",
			"spot":           true,
			"margin":         (marginTradingEnable != nil && *marginTradingEnable == "1"),
			"swap":           false,
			"future":         false,
			"option":         false,
			"active":         active,
			"contract":       false,
			"linear":         nil,
			"inverse":        nil,
			"contractSize":   nil,
			"expiry":         nil,
			"expiryDatetime": nil,
			"strike":         nil,
			"optionType":     nil,
			"precision":      precision,
			"limits":         limits,
			"created":        nil,
			"info":           market,
		}
		if _, ok := filtersByType["MIN_NOTIONAL"]; ok {
			var filter map[string]any = SafeMapTyped(filtersByType, "MIN_NOTIONAL")
			costMin = this.SafeNumber2(filter, "minNotional", "notional")
		}
		result = append(result, entry)
	}

	ch <- AsyncResult[[]MarketInterface]{Value: MarketInterfacesFromList(result)}
	return nil
}

/**
 * @method
 * @name tokocrypto#fetchOrderBook
 * @see https://www.tokocrypto.com/apidocs/#order-book
 * @description fetches information on open orders with bid (buy) and ask (sell) prices, volumes and other data
 * @param {string} symbol unified symbol of the market to fetch the order book for
 * @param {int} [limit] the maximum amount of order book entries to return, symbol type 3 markets accept 5, 10, 20, 50, 100, 500 or 1000 only
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} an [order book structure]{@link https://docs.ccxt.com/?id=order-book-structure}
 */
func (this *Tokocrypto) FetchOrderBookAsync(symbol string, optionalArgs ...any) <-chan AsyncResult[OrderBook] {
	ch := make(chan AsyncResult[OrderBook], 1)
	go this.fetchOrderBookBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Tokocrypto) fetchOrderBookBody(ch chan AsyncResult[OrderBook], symbol string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 0, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var market map[string]any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"symbol": this.GetMarketIdByType(market),
	}
	if limit != nil {
		request["limit"] = limit // default 100, max 5000, see https://github.com/binance/binance-spot-api-docs/blob/master/rest-api.md#order-book
	}
	var response map[string]any = nil
	if this.IsNativeMarket(market) {

		r1 := <-this.PublicGetOpenV1MarketDepth(this.Extend(request, params))
		if r1.Err != nil {
			panic(r1.Err)
		}
		response = r1.Value
	} else {

		r2 := <-this.BinanceGetDepth(this.Extend(request, params))
		if r2.Err != nil {
			panic(r2.Err)
		}
		response = r2.Value
	}
	//
	// future
	//
	//     {
	//         "lastUpdateId":333598053905,
	//         "E":1618631511986,
	//         "T":1618631511964,
	//         "bids":[
	//             ["2493.56","20.189"],
	//             ["2493.54","1.000"],
	//             ["2493.51","0.005"]
	//         ],
	//         "asks":[
	//             ["2493.57","0.877"],
	//             ["2493.62","0.063"],
	//             ["2493.71","12.054"],
	//         ]
	//     }
	// type not 1
	//     {
	//         "code":0,
	//         "msg":"Success",
	//         "data":{
	//            "lastUpdateId":3204783,
	//            "bids":[],
	//            "asks": []
	//         },
	//         "timestamp":1692262634599
	//     }
	var data any = this.SafeDict(response, "data", response)
	var timestamp *int64 = this.SafeInteger2(response, "T", "timestamp")
	var orderbook map[string]any = this.ParseOrderBook(data, symbol, timestamp)
	orderbook["nonce"] = this.SafeInteger(data, "lastUpdateId")

	ch <- AsyncResult[OrderBook]{Value: OrderBookFromMap(orderbook)}
	return nil
}
func (this *Tokocrypto) ParseTrade(trade any, optionalArgs ...any) Trade {
	//
	// aggregate trades
	// https://github.com/binance-exchange/binance-official-api-docs/blob/master/rest-api.md#compressedaggregate-trades-list
	//
	//     {
	//         "a": 26129,         // Aggregate tradeId
	//         "p": "0.01633102",  // Price
	//         "q": "4.70443515",  // Quantity
	//         "f": 27781,         // First tradeId
	//         "l": 27781,         // Last tradeId
	//         "T": 1498793709153, // Timestamp
	//         "m": true,          // Was the buyer the maker?
	//         "M": true           // Was the trade the best price match?
	//     }
	//
	// recent public trades and old public trades
	// https://github.com/binance-exchange/binance-official-api-docs/blob/master/rest-api.md#recent-trades-list
	// https://github.com/binance-exchange/binance-official-api-docs/blob/master/rest-api.md#old-trade-lookup-market_data
	//
	//     {
	//         "id": 28457,
	//         "price": "4.00000100",
	//         "qty": "12.00000000",
	//         "time": 1499865549590,
	//         "isBuyerMaker": true,
	//         "isBestMatch": true
	//     }
	//
	// private trades
	// https://github.com/binance-exchange/binance-official-api-docs/blob/master/rest-api.md#account-trade-list-user_data
	//
	//     {
	//         "symbol": "BNBBTC",
	//         "id": 28457,
	//         "orderId": 100234,
	//         "price": "4.00000100",
	//         "qty": "12.00000000",
	//         "commission": "10.10000000",
	//         "commissionAsset": "BNB",
	//         "time": 1499865549590,
	//         "isBuyer": true,
	//         "isMaker": false,
	//         "isBestMatch": true
	//     }
	//
	// futures trades
	// https://binance-docs.github.io/apidocs/futures/en/#account-trade-list-user_data
	//
	//     {
	//       "accountId": 20,
	//       "buyer": False,
	//       "commission": "-0.07819010",
	//       "commissionAsset": "USDT",
	//       "counterPartyId": 653,
	//       "id": 698759,
	//       "maker": False,
	//       "orderId": 25851813,
	//       "price": "7819.01",
	//       "qty": "0.002",
	//       "quoteQty": "0.01563",
	//       "realizedPnl": "-0.91539999",
	//       "side": "SELL",
	//       "symbol": "BTCUSDT",
	//       "time": 1569514978020
	//     }
	//     {
	//       "symbol": "BTCUSDT",
	//       "id": 477128891,
	//       "orderId": 13809777875,
	//       "side": "SELL",
	//       "price": "38479.55",
	//       "qty": "0.001",
	//       "realizedPnl": "-0.00009534",
	//       "marginAsset": "USDT",
	//       "quoteQty": "38.47955",
	//       "commission": "-0.00076959",
	//       "commissionAsset": "USDT",
	//       "time": 1612733566708,
	//       "positionSide": "BOTH",
	//       "maker": true,
	//       "buyer": false
	//     }
	//
	// { respType: FULL }
	//
	//     {
	//       "price": "4000.00000000",
	//       "qty": "1.00000000",
	//       "commission": "4.00000000",
	//       "commissionAsset": "USDT",
	//       "tradeId": "1234",
	//     }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var timestamp *int64 = this.SafeInteger2(trade, "T", "time")
	var price *string = this.SafeString2(trade, "p", "price")
	var amount *string = this.SafeString2(trade, "q", "qty")
	var cost *string = this.SafeString2(trade, "quoteQty", "baseQty") // inverse futures
	var marketId *string = this.SafeString(trade, "symbol")
	var symbol *string = this.SafeSymbol(marketId, market)
	var id *string = this.SafeString2(trade, "t", "a")
	id = this.SafeString2(trade, "id", "tradeId", id)
	var side *string = nil
	var orderId *string = this.SafeString(trade, "orderId")
	var buyerMaker *bool = this.SafeBool2(trade, "m", "isBuyerMaker")
	var takerOrMaker *string = nil
	if buyerMaker != nil {
		side = SafeStringPtr(func() string {
			if buyerMaker != nil && *buyerMaker {
				return "sell"
			}
			return "buy"
		}()) // this is reversed intentionally
		takerOrMaker = SafeStringPtr("taker")
	} else if this.SafeString(trade, "side") != nil {
		side = this.SafeStringLower(trade, "side")
	} else {
		if this.SafeString(trade, "isBuyer") != nil {
			side = SafeStringPtr(func() string {
				if *this.SafeBool(trade, "isBuyer", false) {
					return "buy"
				}
				return "sell"
			}()) // this is a true side
		}
	}
	var fee map[string]any = nil
	if this.SafeString(trade, "commission") != nil {
		fee = map[string]any{
			"cost":     this.SafeString(trade, "commission"),
			"currency": this.SafeCurrencyCode(this.SafeString(trade, "commissionAsset")),
		}
	}
	if this.SafeString(trade, "isMaker") != nil {
		takerOrMaker = SafeStringPtr(func() string {
			if *this.SafeBool(trade, "isMaker", false) {
				return "maker"
			}
			return "taker"
		}())
	}
	if this.SafeString(trade, "maker") != nil {
		takerOrMaker = SafeStringPtr(func() string {
			if *this.SafeBool(trade, "maker", false) {
				return "maker"
			}
			return "taker"
		}())
	}
	return this.SafeTrade(map[string]any{
		"info":         trade,
		"timestamp":    timestamp,
		"datetime":     this.Iso8601(timestamp),
		"symbol":       symbol,
		"id":           id,
		"order":        orderId,
		"type":         nil,
		"side":         side,
		"takerOrMaker": takerOrMaker,
		"price":        price,
		"amount":       amount,
		"cost":         cost,
		"fee":          fee,
	}, market)
}

/**
 * @method
 * @name tokocrypto#fetchTrades
 * @see https://www.tokocrypto.com/apidocs/#recent-trades-list
 * @see https://www.tokocrypto.com/apidocs/#compressedaggregate-trades-list
 * @description get the list of most recent trades for a particular symbol
 * @param {string} symbol unified symbol of the market to fetch trades for
 * @param {int} [since] timestamp in ms of the earliest trade to fetch
 * @param {int} [limit] the maximum amount of trades to fetch
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {Trade[]} a list of [trade structures]{@link https://docs.ccxt.com/?id=public-trades}
 */
func (this *Tokocrypto) FetchTradesAsync(symbol any, optionalArgs ...any) <-chan AsyncResult[[]Trade] {
	ch := make(chan AsyncResult[[]Trade], 1)
	go this.fetchTradesBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Tokocrypto) fetchTradesBody(ch chan AsyncResult[[]Trade], symbol any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var since *int64 = GetArgInt64Ptr(optionalArgs, 0, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 2, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var market map[string]any = this.Market(symbol)
	var request map[string]any = map[string]any{}
	// the venue routes market data by the symbol type reported by fetchMarkets,
	// not by the quote currency: type 1 markets are served by the binance host
	// with the underscore-less id, every other type by open/v1 with the raw id
	request["symbol"] = this.GetMarketIdByType(market)
	if this.IsNativeMarket(market) {
		if limit != nil {
			request["limit"] = limit
		}
		// open/v1/market/trades answers an empty list for every market, the
		// aggregate endpoint is the one that carries data for these markets

		r1 := <-this.PublicGetOpenV1MarketAggTrades(this.Extend(request, params))
		if r1.Err != nil {
			panic(r1.Err)
		}
		var responseInner map[string]any = r1.Value
		//
		//    {
		//       "code": 0,
		//       "msg": "Success",
		//       "data": {
		//           "list": [
		//                {
		//                    "a": 14433,             // aggregate tradeId
		//                    "p": "495.00",          // price
		//                    "q": "42.00000000",     // quantity
		//                    "f": 15578,             // first tradeId
		//                    "l": 15578,             // last tradeId
		//                    "T": 1787292236948,     // timestamp
		//                    "m": false              // was the buyer the maker?
		//                }
		//            ]
		//        },
		//        "timestamp": 1787318052414
		//    }
		//
		var data map[string]any = SafeMapTyped(responseInner, "data")
		var list []any = SafeListTypedDefault(data, "list", []any{})

		ch <- AsyncResult[[]Trade]{Value: TradesFromList(this.ParseTrades(list, market, since, limit))}
		return nil
	}
	if limit != nil {
		request["limit"] = limit // default = 500, maximum = 1000
	}
	var defaultMethod string = "binanceGetTrades"
	var method *string = this.SafeString(this.Options, "fetchTradesMethod", defaultMethod)
	var response []any = nil
	if (method != nil && *method == "binanceGetAggTrades") && (since != nil) {
		request["startTime"] = since
		// https://github.com/ccxt/ccxt/issues/6400
		// https://github.com/binance-exchange/binance-official-api-docs/blob/master/rest-api.md#compressedaggregate-trades-list
		request["endTime"] = this.Sum(since, 3600000)

		listEp1330 := <-this.BinanceGetAggTrades(this.Extend(request, params))
		if listEp1330.Err != nil {
			panic(listEp1330.Err)
		}
		response = listEp1330.Value
	} else {

		listEp1333 := <-this.BinanceGetTrades(this.Extend(request, params))
		if listEp1333.Err != nil {
			panic(listEp1333.Err)
		}
		response = listEp1333.Value
	}
	//
	// Caveats:
	// - default limit (500) applies only if no other parameters set, trades up
	//   to the maximum limit may be returned to satisfy other parameters
	// - if both limit and time window is set and time window contains more
	//   trades than the limit then the last trades from the window are returned
	// - 'tradeId' accepted and returned by this method is "aggregate" trade id
	//   which is different from actual trade id
	// - setting both fromId and time window results in error
	//
	// aggregate trades
	//
	//     [
	//         {
	//             "a": 26129,         // Aggregate tradeId
	//             "p": "0.01633102",  // Price
	//             "q": "4.70443515",  // Quantity
	//             "f": 27781,         // First tradeId
	//             "l": 27781,         // Last tradeId
	//             "T": 1498793709153, // Timestamp
	//             "m": true,          // Was the buyer the maker?
	//             "M": true           // Was the trade the best price match?
	//         }
	//     ]
	//
	// recent public trades and historical public trades
	//
	//     [
	//         {
	//             "id": 28457,
	//             "price": "4.00000100",
	//             "qty": "12.00000000",
	//             "time": 1499865549590,
	//             "isBuyerMaker": true,
	//             "isBestMatch": true
	//         }
	//     ]
	//
	var responseList []any = this.ToArray(response)

	ch <- AsyncResult[[]Trade]{Value: TradesFromList(this.ParseTrades(responseList, market, since, limit))}
	return nil
}
func (this *Tokocrypto) ParseTicker(ticker any, optionalArgs ...any) Ticker {
	//
	//     {
	//         "symbol": "ETHBTC",
	//         "priceChange": "0.00068700",
	//         "priceChangePercent": "2.075",
	//         "weightedAvgPrice": "0.03342681",
	//         "prevClosePrice": "0.03310300",
	//         "lastPrice": "0.03378900",
	//         "lastQty": "0.07700000",
	//         "bidPrice": "0.03378900",
	//         "bidQty": "7.16800000",
	//         "askPrice": "0.03379000",
	//         "askQty": "24.00000000",
	//         "openPrice": "0.03310200",
	//         "highPrice": "0.03388900",
	//         "lowPrice": "0.03306900",
	//         "volume": "205478.41000000",
	//         "quoteVolume": "6868.48826294",
	//         "openTime": 1601469986932,
	//         "closeTime": 1601556386932,
	//         "firstId": 196098772,
	//         "lastId": 196186315,
	//         "count": 87544
	//     }
	//
	// coinm
	//     {
	//         "baseVolume": "214549.95171161",
	//         "closeTime": "1621965286847",
	//         "count": "1283779",
	//         "firstId": "152560106",
	//         "highPrice": "39938.3",
	//         "lastId": "153843955",
	//         "lastPrice": "37993.4",
	//         "lastQty": "1",
	//         "lowPrice": "36457.2",
	//         "openPrice": "37783.4",
	//         "openTime": "1621878840000",
	//         "pair": "BTCUSD",
	//         "priceChange": "210.0",
	//         "priceChangePercent": "0.556",
	//         "symbol": "BTCUSD_PERP",
	//         "volume": "81990451",
	//         "weightedAvgPrice": "38215.08713747"
	//     }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var timestamp *int64 = this.SafeInteger(ticker, "closeTime")
	var marketId *string = this.SafeString(ticker, "symbol")
	var symbol *string = this.SafeSymbol(marketId, market)
	var last *string = this.SafeString(ticker, "lastPrice")
	var isCoinm bool = (this.SafeString(ticker, "baseVolume") != nil)
	var baseVolume *string = nil
	var quoteVolume *string = nil
	if isCoinm {
		baseVolume = this.SafeString(ticker, "baseVolume")
		quoteVolume = this.SafeString(ticker, "volume")
	} else {
		baseVolume = this.SafeString(ticker, "volume")
		quoteVolume = this.SafeString(ticker, "quoteVolume")
	}
	return this.SafeTicker(map[string]any{
		"symbol":        symbol,
		"timestamp":     timestamp,
		"datetime":      this.Iso8601(timestamp),
		"high":          this.SafeString(ticker, "highPrice"),
		"low":           this.SafeString(ticker, "lowPrice"),
		"bid":           this.SafeString(ticker, "bidPrice"),
		"bidVolume":     this.SafeString(ticker, "bidQty"),
		"ask":           this.SafeString(ticker, "askPrice"),
		"askVolume":     this.SafeString(ticker, "askQty"),
		"vwap":          this.SafeString(ticker, "weightedAvgPrice"),
		"open":          this.SafeString(ticker, "openPrice"),
		"close":         last,
		"last":          last,
		"previousClose": this.SafeString(ticker, "prevClosePrice"),
		"change":        this.SafeString(ticker, "priceChange"),
		"percentage":    this.SafeString(ticker, "priceChangePercent"),
		"average":       nil,
		"baseVolume":    baseVolume,
		"quoteVolume":   quoteVolume,
		"info":          ticker,
	}, market)
}

/**
 * @method
 * @name tokocrypto#fetchTickers
 * @see https://binance-docs.github.io/apidocs/spot/en/#24hr-ticker-price-change-statistics
 * @description fetches price tickers for multiple markets, statistical information calculated over the past 24 hours for each market
 * @param {string[]|undefined} symbols unified symbols of the markets to fetch the ticker for, all market tickers are returned if not assigned
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a dictionary of [ticker structures]{@link https://docs.ccxt.com/?id=ticker-structure}
 */
func (this *Tokocrypto) FetchTickersAsync(optionalArgs ...any) <-chan AsyncResult[map[string]Ticker] {
	ch := make(chan AsyncResult[map[string]Ticker], 1)
	go this.fetchTickersBody(ch, optionalArgs...)
	return ch
}
func (this *Tokocrypto) fetchTickersBody(ch chan AsyncResult[map[string]Ticker], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var symbols []string = GetArgStringSlice(optionalArgs, 0, nil)
	_ = symbols
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	// the binance backed host is the only source of 24hr statistics, so the
	// result omits the native markets instead of raising for them, unlike
	// the single symbol fetchTicker

	r1 := <-this.BinanceGetTicker24hr(params)
	if r1.Err != nil {
		panic(r1.Err)
	}
	response := r1.Value
	if !IsArray(response) {

		// a user-supplied symbol param makes the endpoint answer a single
		// ticker object, the unified fetchTickers contract returns a
		// symbol-keyed dict either way
		ch <- AsyncResult[map[string]Ticker]{Value: TickerMapFromMap(this.ParseTickers([]any{response}, symbols))}
		return nil
	}

	ch <- AsyncResult[map[string]Ticker]{Value: TickerMapFromMap(this.ParseTickers(response, symbols))}
	return nil
}

/**
 * @ignore
 * @method
 * @name tokocrypto#isNativeMarket
 * @description whether a market is served by the tokocrypto native endpoints instead of the binance backed host
 * @param {object} market a unified market structure
 * @returns {boolean} true when the symbol type of the market is known and is not 1
 */
func (this *Tokocrypto) IsNativeMarket(market map[string]any) bool {
	var marketInfo map[string]any = SafeMapTyped(market, "info")
	var symbolType *string = this.SafeString(marketInfo, "type")
	// a market with an unknown symbol type falls back to the binance backed
	// host, the route that answers with data for every symbol type 1 market
	// and errors out loudly for the others, whereas open/v1 would answer an
	// empty list for them
	return (symbolType != nil) && (symbolType == nil || *symbolType != "1")
}

/**
 * @ignore
 * @method
 * @name tokocrypto#getMarketIdByType
 * @description the market id spelling expected by the host that serves the market
 * @param {object} market a unified market structure
 * @returns {string} the raw market id for native markets, the id without the underscore separator otherwise
 */
func (this *Tokocrypto) GetMarketIdByType(market map[string]any) any {
	if this.IsNativeMarket(market) {
		return this.SafeString(market, "id")
	}
	return *this.SafeString(market, "baseId", "") + *this.SafeString(market, "quoteId", "")
}

/**
 * @method
 * @name tokocrypto#fetchTicker
 * @see https://binance-docs.github.io/apidocs/spot/en/#24hr-ticker-price-change-statistics
 * @description fetches a price ticker, a statistical calculation with the information calculated over the past 24 hours for a specific market
 * @param {string} symbol unified symbol of the market to fetch the ticker for
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a [ticker structure]{@link https://docs.ccxt.com/?id=ticker-structure}
 */
func (this *Tokocrypto) FetchTickerAsync(symbol string, optionalArgs ...any) <-chan AsyncResult[Ticker] {
	ch := make(chan AsyncResult[Ticker], 1)
	go this.fetchTickerBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Tokocrypto) fetchTickerBody(ch chan AsyncResult[Ticker], symbol string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var market map[string]any = this.Market(symbol)
	if this.IsNativeMarket(market) {
		panic(NotSupported(this.Id + " fetchTicker() does not support " + symbol + " yet, the venue serves 24hr ticker statistics only for its binance backed markets"))
	}
	var request map[string]any = map[string]any{
		"symbol": this.GetMarketIdByType(market),
	}

	r1 := <-this.BinanceGetTicker24hr(this.Extend(request, params))
	if r1.Err != nil {
		panic(r1.Err)
	}
	response := r1.Value
	if IsArray(response) {
		var firstTicker map[string]any = this.SafeDictMap(response, 0, map[string]any{})

		ch <- AsyncResult[Ticker]{Value: this.ParseTicker(firstTicker, market)}
		return nil
	}

	ch <- AsyncResult[Ticker]{Value: this.ParseTicker(response, market)}
	return nil
}

/**
 * @method
 * @name tokocrypto#fetchBidsAsks
 * @see https://binance-docs.github.io/apidocs/spot/en/#symbol-order-book-ticker
 * @description fetches the bid and ask price and volume for multiple markets
 * @param {string[]|undefined} symbols unified symbols of the markets to fetch the bids and asks for, all markets are returned if not assigned
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a dictionary of [ticker structures]{@link https://docs.ccxt.com/?id=ticker-structure}
 */
func (this *Tokocrypto) FetchBidsAsksAsync(optionalArgs ...any) <-chan AsyncResult[map[string]Ticker] {
	ch := make(chan AsyncResult[map[string]Ticker], 1)
	go this.fetchBidsAsksBody(ch, optionalArgs...)
	return ch
}
func (this *Tokocrypto) fetchBidsAsksBody(ch chan AsyncResult[map[string]Ticker], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var symbols []string = GetArgStringSlice(optionalArgs, 0, nil)
	_ = symbols
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}

	listEp1612 := <-this.BinanceGetTickerBookTicker(params)
	if listEp1612.Err != nil {
		panic(listEp1612.Err)
	}
	var response []any = listEp1612.Value

	ch <- AsyncResult[map[string]Ticker]{Value: TickerMapFromMap(this.ParseTickers(response, symbols))}
	return nil
}
func (this *Tokocrypto) ParseOHLCV(ohlcv any, optionalArgs ...any) OHLCV {
	// when api method = publicGetKlines || fapiPublicGetKlines || dapiPublicGetKlines
	//     [
	//         1591478520000, // open time
	//         "0.02501300",  // open
	//         "0.02501800",  // high
	//         "0.02500000",  // low
	//         "0.02500000",  // close
	//         "22.19000000", // volume
	//         1591478579999, // close time
	//         "0.55490906",  // quote asset volume
	//         40,            // number of trades
	//         "10.92900000", // taker buy base asset volume
	//         "0.27336462",  // taker buy quote asset volume
	//         "0"            // ignore
	//     ]
	//
	//  when api method = fapiPublicGetMarkPriceKlines || fapiPublicGetIndexPriceKlines
	//     [
	//         [
	//         1591256460000,          // Open time
	//         "9653.29201333",        // Open
	//         "9654.56401333",        // High
	//         "9653.07367333",        // Low
	//         "9653.07367333",        // Close (or latest price)
	//         "0",                    // Ignore
	//         1591256519999,          // Close time
	//         "0",                    // Ignore
	//         60,                     // Number of basic data
	//         "0",                    // Ignore
	//         "0",                    // Ignore
	//         "0"                     // Ignore
	//         ]
	//     ]
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	return OHLCVFromList([]any{this.SafeInteger(ohlcv, 0), this.SafeNumber(ohlcv, 1), this.SafeNumber(ohlcv, 2), this.SafeNumber(ohlcv, 3), this.SafeNumber(ohlcv, 4), this.SafeNumber(ohlcv, 5)})
}

/**
 * @method
 * @name tokocrypto#fetchOHLCV
 * @see https://binance-docs.github.io/apidocs/spot/en/#kline-candlestick-data
 * @description fetches historical candlestick data containing the open, high, low, and close price, and the volume of a market
 * @param {string} symbol unified symbol of the market to fetch OHLCV data for
 * @param {string} timeframe the length of time each candle represents
 * @param {int} [since] timestamp in ms of the earliest candle to fetch
 * @param {int} [limit] the maximum amount of candles to fetch
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.price] "mark" or "index" for mark price and index price candles
 * @param {int} [params.until] timestamp in ms of the latest candle to fetch
 * @returns {int[][]} A list of candles ordered as timestamp, open, high, low, close, volume
 */
func (this *Tokocrypto) FetchOHLCVAsync(symbol string, optionalArgs ...any) <-chan AsyncResult[[]OHLCV] {
	ch := make(chan AsyncResult[[]OHLCV], 1)
	go this.fetchOHLCVBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Tokocrypto) fetchOHLCVBody(ch chan AsyncResult[[]OHLCV], symbol string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var timeframe string = GetArgString(optionalArgs, 0, "1m")
	_ = timeframe
	var since *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var market map[string]any = this.Market(symbol)
	// binance docs say that the default limit 500, max 1500 for futures, max 1000 for spot markets
	// the reality is that the time range wider than 500 candles won't work right
	var defaultLimit int = 500
	var maxLimit int = 1500
	var price *string = this.SafeString(params, "price")
	var until *int64 = this.SafeInteger(params, "until")
	var paramsOmitted map[string]any = this.OmitDict(params, []any{"price", "until"})
	var limitValue any = defaultLimit
	if limit != nil {
		limitValue = mathMin(limit, maxLimit)
	}
	var request map[string]any = map[string]any{
		"interval": this.SafeString(this.Timeframes, timeframe, timeframe),
		"limit":    limitValue,
	}
	if price != nil && *price == "index" {
		request["pair"] = market["id"] // Index price takes this argument instead of symbol
	} else {
		request["symbol"] = this.GetMarketIdByType(market)
	}
	// const duration = this.parseTimeframe (timeframe);
	if since != nil {
		request["startTime"] = since
	}
	if until != nil {
		request["endTime"] = until
	}
	var response any = nil
	if this.IsNativeMarket(market) {

		r1 := <-this.PublicGetOpenV1MarketKlines(this.Extend(request, paramsOmitted))
		if r1.Err != nil {
			panic(r1.Err)
		}
		response = r1.Raw
	} else {

		r2 := <-this.BinanceGetKlines(this.Extend(request, paramsOmitted))
		if r2.Err != nil {
			panic(r2.Err)
		}
		response = r2.Raw
	}
	//
	// binanceGetKlines
	//
	//     [
	//         [1591478520000,"0.02501300","0.02501800","0.02500000","0.02500000","22.19000000",1591478579999,"0.55490906",40,"10.92900000","0.27336462","0"],
	//         [1591478580000,"0.02499600","0.02500900","0.02499400","0.02500300","21.34700000",1591478639999,"0.53370468",24,"7.53800000","0.18850725","0"],
	//         [1591478640000,"0.02500800","0.02501100","0.02500300","0.02500800","154.14200000",1591478699999,"3.85405839",97,"5.32300000","0.13312641","0"],
	//     ]
	//
	// publicGetOpenV1MarketKlines
	//
	//     {
	//         "code": 0,
	//         "msg": "Success",
	//         "data": [
	//             [1787817600000,"521.00","537.00","521.00","537.00","1188.29000000",1787821199999,"632572.93",9,"1027.29000000","548331.93","0"],
	//         ],
	//         "timestamp": 1787822924930
	//     }
	//
	// publicGetOpenV1MarketKlines, legacy envelope
	//
	//     {
	//         "code": 0,
	//         "msg": "Success",
	//         "data": {
	//             "list": [
	//                 [1591478520000,"0.02501300","0.02501800","0.02500000","0.02500000","22.19000000",1591478579999,"0.55490906",40,"10.92900000","0.27336462","0"],
	//             ]
	//         },
	//         "timestamp": 1659492212507
	//     }
	//
	var data []any = []any{}
	if IsArray(response) {
		data = ArrayTyped(response)
	} else {
		var dataList []any = SafeListTyped(response, "data")
		if dataList != nil {
			data = dataList
		} else {
			var dataDict map[string]any = SafeMapTyped(response, "data")
			data = ArrayTyped(this.SafeList(dataDict, "list", []any{}))
		}
	}

	ch <- AsyncResult[[]OHLCV]{Value: OHLCVsFromList(this.ParseOHLCVs(data, market, timeframe, since, limitValue))}
	return nil
}

/**
 * @method
 * @name tokocrypto#fetchBalance
 * @see https://www.tokocrypto.com/apidocs/#account-information-signed
 * @description query for balance and get the amount of funds available for trading or funds locked in orders
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.type] 'spot', 'margin', 'swap', 'future', 'savings' or 'funding'
 * @param {string} [params.marginMode] 'cross' or 'isolated', for margin trading, uses this.options.defaultMarginMode if not passed, defaults to undefined/None/null
 * @param {string[]|undefined} [params.symbols] unified market symbols, only used in isolated margin mode
 * @returns {object} a [balance structure]{@link https://docs.ccxt.com/?id=balance-structure}
 */
func (this *Tokocrypto) FetchBalanceAsync(optionalArgs ...any) <-chan AsyncResult[Balances] {
	ch := make(chan AsyncResult[Balances], 1)
	go this.fetchBalanceBody(ch, optionalArgs...)
	return ch
}
func (this *Tokocrypto) fetchBalanceBody(ch chan AsyncResult[Balances], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var defaultType *string = this.SafeString2(this.Options, "fetchBalance", "defaultType", "spot")
	var typeVar *string = this.SafeString(params, "type", defaultType)
	var defaultMarginMode *string = this.SafeString2(this.Options, "marginMode", "defaultMarginMode")
	var marginMode *string = this.SafeStringLower(params, "marginMode", defaultMarginMode)
	var request map[string]any = map[string]any{}

	r1 := <-this.PrivateGetOpenV1AccountSpot(this.Extend(request, params))
	if r1.Err != nil {
		panic(r1.Err)
	}
	var response map[string]any = r1.Value

	//
	// spot
	//
	//     {
	//         "code":0,
	//         "msg":"Success",
	//         "data":{
	//             "makerCommission":"0.00100000",
	//             "takerCommission":"0.00100000",
	//             "buyerCommission":"0.00000000",
	//             "sellerCommission":"0.00000000",
	//             "canTrade":1,
	//             "canWithdraw":1,
	//             "canDeposit":1,
	//             "status":1,
	//             "accountAssets":[
	//                 {"asset":"1INCH","free":"0","locked":"0"},
	//                 {"asset":"AAVE","free":"0","locked":"0"},
	//                 {"asset":"ACA","free":"0","locked":"0"}
	//             ],
	//         },
	//         "timestamp":1659666786943
	//     }
	//
	ch <- AsyncResult[Balances]{Value: BalancesFromMap(this.ParseBalanceCustom(response, typeVar, marginMode))}
	return nil
}
func (this *Tokocrypto) ParseBalanceCustom(response any, optionalArgs ...any) map[string]any {
	var typeVar *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = typeVar
	var marginMode *string = GetArgStringPtr(optionalArgs, 1, nil)
	_ = marginMode
	var timestamp *int64 = this.SafeInteger(response, "updateTime")
	var result map[string]any = map[string]any{
		"info":      response,
		"timestamp": timestamp,
		"datetime":  this.Iso8601(timestamp),
	}
	var data map[string]any = SafeMapTyped(response, "data")
	var balances []any = SafeListTyped(data, "accountAssets")
	for i := 0; i < len(balances); i++ {
		var balance map[string]any = SafeMapTyped(balances, i)
		var currencyId *string = this.SafeString(balance, "asset")
		var code *string = this.SafeCurrencyCode(currencyId)
		var account map[string]any = this.Account()
		account["free"] = this.SafeString(balance, "free")
		account["used"] = this.SafeString(balance, "locked")
		if code != nil {
			result[*code] = account
		}
	}
	return this.SafeBalance(result).(map[string]any)
}
func (this *Tokocrypto) ParseOrderStatus(status *string) *string {
	var statuses map[string]any = map[string]any{
		"-2":               "open",
		"0":                "open",
		"1":                "open",
		"2":                "closed",
		"3":                "canceled",
		"4":                "canceling",
		"5":                "rejected",
		"6":                "expired",
		"NEW":              "open",
		"PARTIALLY_FILLED": "open",
		"FILLED":           "closed",
		"CANCELED":         "canceled",
		"PENDING_CANCEL":   "canceling",
		"REJECTED":         "rejected",
		"EXPIRED":          "expired",
	}
	return this.SafeString(statuses, status, status)
}
func (this *Tokocrypto) ParseOrder(order any, optionalArgs ...any) Order {
	//
	// spot
	//
	//     {
	//         "symbol": "LTCBTC",
	//         "orderId": 1,
	//         "clientOrderId": "myOrder1",
	//         "price": "0.1",
	//         "origQty": "1.0",
	//         "executedQty": "0.0",
	//         "cummulativeQuoteQty": "0.0",
	//         "status": "NEW",
	//         "timeInForce": "GTC",
	//         "type": "LIMIT",
	//         "side": "BUY",
	//         "stopPrice": "0.0",
	//         "icebergQty": "0.0",
	//         "time": 1499827319559,
	//         "updateTime": 1499827319559,
	//         "isWorking": true
	//     }
	// createOrder
	//     {
	//         "orderId": "145265071",
	//         "bOrderListId": "0",
	//         "clientId": "49c09c3c2cd54419a59c05441f517b3c",
	//         "bOrderId": "35247529",
	//         "symbol": "USDT_BIDR",
	//         "symbolType": "1",
	//         "side": "0",
	//         "type": "1",
	//         "price": "11915",
	//         "origQty": "2",
	//         "origQuoteQty": "23830.00",
	//         "executedQty": "0.00000000",
	//         "executedPrice": "0",
	//         "executedQuoteQty": "0.00",
	//         "timeInForce": "1",
	//         "stopPrice": "0",
	//         "icebergQty": "0",
	//         "status": "0",
	//         "createTime": "1662711074372"
	//     }
	//
	// createOrder with { "newOrderRespType": "FULL" }
	//
	//     {
	//       "symbol": "BTCUSDT",
	//       "orderId": 5403233939,
	//       "orderListId": -1,
	//       "clientOrderId": "x-R4BD3S825e669e75b6c14f69a2c43e",
	//       "transactTime": 1617151923742,
	//       "price": "0.00000000",
	//       "origQty": "0.00050000",
	//       "executedQty": "0.00050000",
	//       "cummulativeQuoteQty": "29.47081500",
	//       "status": "FILLED",
	//       "timeInForce": "GTC",
	//       "type": "MARKET",
	//       "side": "BUY",
	//       "fills": [
	//         {
	//           "price": "58941.63000000",
	//           "qty": "0.00050000",
	//           "commission": "0.00007050",
	//           "commissionAsset": "BNB",
	//           "tradeId": 737466631
	//         }
	//       ]
	//     }
	//
	// delivery
	//
	//     {
	//       "orderId": "18742727411",
	//       "symbol": "ETHUSD_PERP",
	//       "pair": "ETHUSD",
	//       "status": "FILLED",
	//       "clientOrderId": "x-xcKtGhcu3e2d1503fdd543b3b02419",
	//       "price": "0",
	//       "avgPrice": "4522.14",
	//       "origQty": "1",
	//       "executedQty": "1",
	//       "cumBase": "0.00221134",
	//       "timeInForce": "GTC",
	//       "type": "MARKET",
	//       "reduceOnly": false,
	//       "closePosition": false,
	//       "side": "SELL",
	//       "positionSide": "BOTH",
	//       "stopPrice": "0",
	//       "workingType": "CONTRACT_PRICE",
	//       "priceProtect": false,
	//       "origType": "MARKET",
	//       "time": "1636061952660",
	//       "updateTime": "1636061952660"
	//     }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var status *string = this.ParseOrderStatus(this.SafeString(order, "status"))
	var marketId *string = this.SafeString(order, "symbol")
	var symbol *string = this.SafeSymbol(marketId, market)
	var filled *string = this.SafeString(order, "executedQty", "0")
	var timestamp *int64 = this.SafeInteger(order, "createTime")
	var average *string = this.SafeString(order, "avgPrice")
	var price *string = this.SafeString2(order, "price", "executedPrice")
	var amount *string = this.SafeString(order, "origQty")
	// - Spot/Margin market: cummulativeQuoteQty
	//   Note this is not the actual cost, since Binance futures uses leverage to calculate margins.
	var cost *string = this.SafeStringN(order, []any{"cummulativeQuoteQty", "cumQuote", "executedQuoteQty", "cumBase"})
	var id *string = this.SafeString(order, "orderId")
	var rawOrderType *string = this.SafeStringLower(order, "type")
	var typeVar *string = this.ParseOrderType(rawOrderType)
	var side *string = this.SafeStringLower(order, "side")
	if side != nil && *side == "0" {
		side = SafeStringPtr("buy")
	} else if side != nil && *side == "1" {
		side = SafeStringPtr("sell")
	}
	var fills []any = SafeListTypedDefault(order, "fills", []any{})
	var clientOrderId *string = this.SafeString2(order, "clientOrderId", "clientId")
	var timeInForce *string = this.ParseTimeInForce(this.SafeString(order, "timeInForce"))
	// the order type carries the post only flag on its own, 7 on the open/v1
	// payloads and LIMIT_MAKER on the binance shaped ones, so the time force
	// echoed back by the venue is only the third witness
	var isLimitMaker bool = (rawOrderType != nil && *rawOrderType == "7") || (rawOrderType != nil && *rawOrderType == "limit_maker")
	var postOnly bool = isLimitMaker || (timeInForce != nil && *timeInForce == "PO")
	return this.SafeOrder(map[string]any{
		"info":               order,
		"id":                 id,
		"clientOrderId":      clientOrderId,
		"timestamp":          timestamp,
		"datetime":           this.Iso8601(timestamp),
		"lastTradeTimestamp": nil,
		"symbol":             symbol,
		"type":               typeVar,
		"timeInForce":        timeInForce,
		"postOnly":           postOnly,
		"reduceOnly":         this.SafeBool(order, "reduceOnly"),
		"side":               side,
		"price":              price,
		"triggerPrice":       this.ParseNumber(this.OmitZero(this.SafeString(order, "stopPrice"))),
		"amount":             amount,
		"cost":               cost,
		"average":            average,
		"filled":             filled,
		"remaining":          nil,
		"status":             status,
		"fee":                nil,
		"trades":             fills,
	}, market)
}
func (this *Tokocrypto) ParseTimeInForce(timeInForce *string) *string {
	var timeInForces map[string]any = map[string]any{
		"1":   "GTC",
		"2":   "IOC",
		"3":   "FOK",
		"4":   "PO",
		"GTX": "PO",
	}
	return this.SafeString(timeInForces, timeInForce, timeInForce)
}
func (this *Tokocrypto) ParseOrderType(status *string) *string {
	var statuses map[string]any = map[string]any{
		"2": "market",
		"1": "limit",
		"4": "limit",
		"7": "limit",
	}
	return this.SafeString(statuses, status, status)
}

/**
 * @method
 * @name tokocrypto#createOrder
 * @description create a trade order
 * @see https://www.tokocrypto.com/apidocs/#new-order--signed
 * @param {string} symbol unified symbol of the market to create an order in
 * @param {string} type 'market' or 'limit'
 * @param {string} side 'buy' or 'sell'
 * @param {float} amount how much of currency you want to trade in units of base currency
 * @param {float} [price] the price at which the order is to be fulfilled, in units of the quote currency, ignored in market orders
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {float} [params.triggerPrice] the price at which a trigger order would be triggered
 * @param {float} [params.cost] for spot market buy orders, the quote quantity that can be used as an alternative for the amount
 * @param {string} [params.timeInForce] 'GTC', 'IOC' or 'FOK', defaults to the defaultTimeInForce option on the order types that rest on the book, market orders accept 'IOC' as a no-op and reject the rest
 * @param {bool} [params.postOnly] true for a post only order, the 'PO' and 'GTX' timeInForce spellings do the same
 * @returns {object} an [order structure]{@link https://docs.ccxt.com/?id=order-structure}
 */
func (this *Tokocrypto) CreateOrderAsync(symbol string, typeVar string, side string, amount any, optionalArgs ...any) <-chan AsyncResult[Order] {
	ch := make(chan AsyncResult[Order], 1)
	go this.createOrderBody(ch, symbol, typeVar, side, amount, optionalArgs...)
	return ch
}
func (this *Tokocrypto) createOrderBody(ch chan AsyncResult[Order], symbol string, typeVar string, side string, amount any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var price *float64 = GetArgFloat64Ptr(optionalArgs, 0, nil)
	_ = price
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var market map[string]any = this.Market(symbol)
	var clientOrderId *string = this.SafeString2(params, "clientOrderId", "clientId")
	var requestedType string = strings.ToUpper(typeVar)
	var requestedTimeInForce *string = this.SafeStringUpper(params, "timeInForce")
	var isMarketOrder bool = (requestedType == "MARKET")
	// GTX is the venue spelling of post only, on top of the two unified spellings
	var isPostOnlyTimeInForce bool = (requestedTimeInForce != nil && *requestedTimeInForce == "GTX")
	var postOnlyparamsPostOnlyVariable []any = this.HandlePostOnly(isMarketOrder, isPostOnlyTimeInForce, params)
	var postOnly bool = postOnlyparamsPostOnlyVariable[0].(bool)
	var paramsPostOnly map[string]any = postOnlyparamsPostOnlyVariable[1].(map[string]any)
	// only supported for spot/margin api
	var typeResolved string = typeVar
	if postOnly {
		typeResolved = "LIMIT_MAKER"
	}
	// post only is expressed by the order type here, not by a time force
	var timeInForceResolved *string = requestedTimeInForce
	if postOnly {
		timeInForceResolved = nil
	}
	var initialUppercaseType string = strings.ToUpper(typeResolved)
	var uppercaseType string = initialUppercaseType
	var triggerPrice any = this.SafeValue2(params, "triggerPrice", "stopPrice")
	var paramsRequest any = this.Omit(paramsPostOnly, []any{"clientId", "clientOrderId", "timeInForce"})
	if triggerPrice != nil {
		paramsRequest = this.Omit(paramsRequest, []any{"triggerPrice", "stopPrice"})
		if postOnly {
			panic(InvalidOrder(this.Id + " createOrder() does not support post only trigger orders, the venue has no post only trigger order type"))
		}
		if uppercaseType == "MARKET" {
			uppercaseType = "STOP_LOSS"
		} else if uppercaseType == "LIMIT" {
			uppercaseType = "STOP_LOSS_LIMIT"
		}
	}
	var validOrderTypes any = this.SafeValue(market["info"], "orderTypes")
	if !this.InArray(uppercaseType, validOrderTypes) {
		if initialUppercaseType != uppercaseType {
			panic(InvalidOrder(this.Id + " triggerPrice parameter is not allowed for " + symbol + " " + typeResolved + " orders"))
		} else {
			panic(InvalidOrder(this.Id + " " + typeResolved + " is not a valid order type for the " + symbol + " market"))
		}
	}
	var reverseOrderTypeMapping map[string]any = map[string]any{
		"LIMIT":             1,
		"MARKET":            2,
		"STOP_LOSS":         3,
		"STOP_LOSS_LIMIT":   4,
		"TAKE_PROFIT":       5,
		"TAKE_PROFIT_LIMIT": 6,
		"LIMIT_MAKER":       7,
	}
	var baseId string = *this.SafeString(market, "baseId", "")
	var quoteId string = *this.SafeString(market, "quoteId", "")
	var request map[string]any = map[string]any{
		"symbol": baseId + "_" + quoteId,
		"type":   this.SafeString(reverseOrderTypeMapping, uppercaseType),
	}
	if side == "buy" {
		request["side"] = 0
	} else if side == "sell" {
		request["side"] = 1
	}
	if clientOrderId == nil {
		var broker map[string]any = SafeMapTyped(this.Options, "broker")
		if broker != nil {
			var brokerId *string = this.SafeString(broker, "marketType")
			if brokerId != nil {
				request["clientId"] = *brokerId + this.Uuid22()
			}
		}
	} else {
		request["clientId"] = clientOrderId
	}
	// additional required fields depending on the order type
	var priceIsRequired bool = false
	var triggerPriceIsRequired bool = false
	var quantityIsRequired bool = false
	var timeInForceIsRequired bool = false
	//
	// spot/margin
	//
	//     LIMIT                timeInForce, quantity, price
	//     MARKET               quantity or quoteOrderQty
	//     STOP_LOSS            quantity, stopPrice
	//     STOP_LOSS_LIMIT      timeInForce, quantity, price, stopPrice
	//     TAKE_PROFIT          quantity, stopPrice
	//     TAKE_PROFIT_LIMIT    timeInForce, quantity, price, stopPrice
	//     LIMIT_MAKER          quantity, price
	//
	if uppercaseType == "MARKET" {
		if side == "buy" {
			var marketPrecision map[string]any = SafeMapTyped(market, "precision")
			var precision any = marketPrecision["price"]
			var quoteAmount any = nil
			var createMarketBuyOrderRequiresPrice bool = true
			createMarketBuyOrderRequiresPrice, paramsRequest = this.HandleOptionBoolAndParams(paramsRequest, "createOrder", "createMarketBuyOrderRequiresPrice", true)
			var cost *float64 = this.SafeNumber2(paramsRequest, "cost", "quoteOrderQty")
			paramsRequest = this.Omit(paramsRequest, []any{"cost", "quoteOrderQty"})
			if cost != nil {
				quoteAmount = cost
			} else if createMarketBuyOrderRequiresPrice {
				if price == nil {
					panic(InvalidOrder(this.Id + " createOrder() requires the price argument for market buy orders to calculate the total cost to spend (amount * price), alternatively set the createMarketBuyOrderRequiresPrice option or param to false and pass the cost to spend (quote quantity) in the amount argument"))
				} else {
					var amountString *string = this.NumberToString(amount)
					var priceString *string = this.NumberToString(price)
					quoteAmount = Precise.StringMul(amountString, priceString)
				}
			} else {
				quoteAmount = amount
			}
			request["quoteOrderQty"] = this.DecimalToPrecision(quoteAmount, TRUNCATE, precision, this.PrecisionMode)
		} else {
			quantityIsRequired = true
		}
	} else if uppercaseType == "LIMIT" {
		priceIsRequired = true
		quantityIsRequired = true
		timeInForceIsRequired = true
	} else if (uppercaseType == "STOP_LOSS") || (uppercaseType == "TAKE_PROFIT") {
		triggerPriceIsRequired = true
		quantityIsRequired = true
		if (market["linear"] == true) || (market["inverse"] == true) {
			priceIsRequired = true
		}
	} else if (uppercaseType == "STOP_LOSS_LIMIT") || (uppercaseType == "TAKE_PROFIT_LIMIT") {
		quantityIsRequired = true
		triggerPriceIsRequired = true
		priceIsRequired = true
		timeInForceIsRequired = true
	} else if uppercaseType == "LIMIT_MAKER" {
		priceIsRequired = true
		quantityIsRequired = true
	}
	if quantityIsRequired {
		request["quantity"] = this.AmountToPrecision(symbol, amount)
	}
	if priceIsRequired {
		if price == nil {
			panic(InvalidOrder(this.Id + " createOrder() requires a price argument for a " + typeResolved + " order"))
		}
		request["price"] = this.PriceToPrecision(symbol, price)
	}
	if triggerPriceIsRequired {
		if triggerPrice == nil {
			panic(InvalidOrder(this.Id + " createOrder() requires a triggerPrice extra param for a " + typeResolved + " order"))
		} else {
			request["stopPrice"] = this.PriceToPrecision(symbol, triggerPrice)
		}
	}
	if timeInForceIsRequired {
		var defaultTimeInForce *string = this.SafeString(this.Options, "defaultTimeInForce", "GTC")
		var timeInForce *string = defaultTimeInForce
		if timeInForceResolved != nil {
			timeInForce = timeInForceResolved
		}
		// the endpoint takes the time force as a numeric code, post only is
		// placed as a LIMIT_MAKER order rather than as the GTX code
		var timeInForceCodes map[string]any = map[string]any{
			"GTC": "1",
			"IOC": "2",
			"FOK": "3",
		}
		var timeInForceCode *string = this.SafeString(timeInForceCodes, timeInForce)
		if timeInForceCode == nil {
			panic(InvalidOrder(this.Id + " createOrder() does not support the " + *timeInForce + " timeInForce, use GTC, IOC, FOK or the postOnly parameter"))
		}
		request["timeInForce"] = timeInForceCode
	} else if timeInForceResolved != nil {
		// a market order fills immediately or not at all, so an IOC asks for
		// what the order type already does and gets accepted as a no-op, while
		// any other time force would be a promise the venue cannot keep here
		var isRedundantImmediateOrCancel bool = isMarketOrder && (timeInForceResolved != nil && *timeInForceResolved == "IOC")
		if !isRedundantImmediateOrCancel {
			panic(NotSupported(this.Id + " createOrder() does not support the " + *timeInForceResolved + " timeInForce for " + typeVar + " orders"))
		}
	}

	r1 := <-this.PrivatePostOpenV1Orders(this.Extend(request, paramsRequest))
	if r1.Err != nil {
		panic(r1.Err)
	}
	var response map[string]any = r1.Value
	//
	//     {
	//         "code": 0,
	//         "msg": "Success",
	//         "data": {
	//             "orderId": 145264846,
	//             "bOrderListId": 0,
	//             "clientId": "4ee2ab5e55e74b358eaf98079c670d17",
	//             "bOrderId": 35247499,
	//             "symbol": "USDT_BIDR",
	//             "symbolType": 1,
	//             "side": 0,
	//             "type": 1,
	//             "price": "11915",
	//             "origQty": "2",
	//             "origQuoteQty": "23830.00",
	//             "executedQty": "0.00000000",
	//             "executedPrice": "0",
	//             "executedQuoteQty": "0.00",
	//             "timeInForce": 1,
	//             "stopPrice": 0,
	//             "icebergQty": "0",
	//             "status": 0,
	//             "createTime": 1662710994848
	//         },
	//         "timestamp": 1662710994975
	//     }
	//
	var rawOrder map[string]any = this.SafeDictMap(response, "data", map[string]any{})

	ch <- AsyncResult[Order]{Value: this.ParseOrder(rawOrder, market)}
	return nil
}

/**
 * @method
 * @name tokocrypto#fetchOrder
 * @see https://www.tokocrypto.com/apidocs/#query-order-signed
 * @description fetches information on an order made by the user
 * @param {string} id order id
 * @param {string} symbol unified symbol of the market the order was made in
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} An [order structure]{@link https://docs.ccxt.com/?id=order-structure}
 */
func (this *Tokocrypto) FetchOrderAsync(id string, optionalArgs ...any) <-chan AsyncResult[Order] {
	ch := make(chan AsyncResult[Order], 1)
	go this.fetchOrderBody(ch, id, optionalArgs...)
	return ch
}
func (this *Tokocrypto) fetchOrderBody(ch chan AsyncResult[Order], id string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var symbol *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = symbol
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	var request map[string]any = map[string]any{
		"orderId": id,
	}

	r := <-this.PrivateGetOpenV1Orders(this.Extend(request, params))
	if r.Err != nil {
		panic(r.Err)
	}
	var response map[string]any = r.Value
	//
	//     {
	//         "code": 0,
	//         "msg": "Success",
	//         "data": {
	//             "list": [{
	//                 "orderId": "145221985",
	//                 "clientId": "201515331fd64d03aedbe687a38152e3",
	//                 "bOrderId": "35239632",
	//                 "bOrderListId": "0",
	//                 "symbol": "USDT_BIDR",
	//                 "symbolType": 1,
	//                 "side": 0,
	//                 "type": 1,
	//                 "price": "11907",
	//                 "origQty": "2",
	//                 "origQuoteQty": "23814",
	//                 "executedQty": "0",
	//                 "executedPrice": "0",
	//                 "executedQuoteQty": "0",
	//                 "timeInForce": 1,
	//                 "stopPrice": "0",
	//                 "icebergQty": "0",
	//                 "status": 0,
	//                 "createTime": 1662699360000
	//             }]
	//         },
	//         "timestamp": 1662710056523
	//     }
	//
	var data map[string]any = SafeMapTyped(response, "data")
	var list []any = SafeListTyped(data, "list")
	var rawOrder map[string]any = this.SafeDictMap(list, 0, map[string]any{})

	ch <- AsyncResult[Order]{Value: this.ParseOrder(rawOrder)}
	return nil
}

