func (this *Tokocrypto) ParseTransaction(transaction any, optionalArgs ...any) Transaction {
	//
	// fetchDeposits
	//
	//     {
	//         "id": 5167969,
	//         "asset": "BIDR",
	//         "network": "BSC",
	//         "address": "0x101a925704f6ff13295ab8dd7a60988d116aaedf",
	//         "addressTag": "",
	//         "txId": "113409337867",
	//         "amount": "15000",
	//         "transferType": 1,
	//         "status": 1,
	//         "insertTime": "1659429390000"
	//     }
	//
	// fetchWithdrawals
	//
	//     {
	//         "id": 4245859,
	//         "clientId": "198",
	//         "asset": "BIDR",
	//         "network": "BSC",
	//         "address": "0xff1c75149cc492e7d5566145b859fcafc900b6e9",
	//         "addressTag": "",
	//         "amount": "10000",
	//         "fee": "0",
	//         "txId": "113501794501",
	//         "transferType": 1,
	//         "status": 10,
	//         "createTime": 1659521314413
	//     }
	//
	// withdraw
	//
	//     {
	//         "code": 0,
	//         "msg": "成功",
	//         "data": {
	//             "withdrawId":"12"
	//         },
	//         "timestamp": 1571745049095
	//     }
	//
	var currency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = currency
	var address *string = this.SafeString(transaction, "address")
	var tag *string = this.SafeString(transaction, "addressTag") // set but unused
	if tag != nil {
		if len(*tag) < 1 {
			tag = nil
		}
	}
	var txid *string = this.SafeString(transaction, "txId")
	if (txid != nil) && (strings.Index(*txid, "Internal transfer ") >= 0) {
		txid = SafeStringPtr(func() string {
			if txid == nil {
				return ""
			}
			str := *txid
			return str[18:]
		}())
	}
	var currencyId *string = this.SafeString2(transaction, "coin", "fiatCurrency")
	var code *string = this.SafeCurrencyCode(currencyId, currency)
	var timestamp *int64 = nil
	var insertTime *int64 = this.SafeInteger(transaction, "insertTime")
	var createTime *int64 = this.SafeInteger2(transaction, "createTime", "timestamp")
	var typeVar *string = this.SafeString(transaction, "type")
	if typeVar == nil {
		if (insertTime != nil) && (createTime == nil) {
			typeVar = SafeStringPtr("deposit")
			timestamp = insertTime
		} else if (insertTime == nil) && (createTime != nil) {
			typeVar = SafeStringPtr("withdrawal")
			timestamp = createTime
		}
	}
	var feeCost *float64 = this.SafeNumber2(transaction, "transactionFee", "totalFee")
	var fee map[string]any = map[string]any{
		"currency": nil,
		"cost":     nil,
		"rate":     nil,
	}
	if feeCost != nil {
		fee["currency"] = code
		fee["cost"] = feeCost
	}
	var internalRaw *int64 = this.SafeInteger(transaction, "transferType")
	var internal bool = false
	if internalRaw != nil {
		internal = true
	}
	var id *string = this.SafeString(transaction, "id")
	if id == nil {
		var data map[string]any = SafeMapTyped(transaction, "data")
		id = this.SafeString(data, "withdrawId")
		typeVar = SafeStringPtr("withdrawal")
	}
	return TransactionFromMap(map[string]any{
		"info":        transaction,
		"id":          id,
		"txid":        txid,
		"type":        typeVar,
		"currency":    code,
		"network":     this.NetworkIdToCode(this.SafeString(transaction, "network"), code),
		"amount":      this.SafeNumber(transaction, "amount"),
		"status":      this.ParseTransactionStatusByType(this.SafeString(transaction, "status"), typeVar),
		"timestamp":   timestamp,
		"datetime":    this.Iso8601(timestamp),
		"address":     address,
		"addressFrom": nil,
		"addressTo":   address,
		"tag":         tag,
		"tagFrom":     nil,
		"tagTo":       tag,
		"updated":     this.SafeInteger2(transaction, "successTime", "updateTime"),
		"comment":     nil,
		"internal":    internal,
		"fee":         fee,
	})
}

/**
 * @method
 * @name tokocrypto#withdraw
 * @see https://www.tokocrypto.com/apidocs/#withdraw-signed
 * @description make a withdrawal
 * @param {string} code unified currency code
 * @param {float} amount the amount to withdraw
 * @param {string} address the address to withdraw to
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.tag] memo / destination tag, required for currencies in options['withdrawTagRequiredCurrencies']
 * @returns {object} a [transaction structure]{@link https://docs.ccxt.com/?id=transaction-structure}
 */
func (this *Tokocrypto) WithdrawAsync(code string, amount any, address any, optionalArgs ...any) <-chan AsyncResult[Transaction] {
	ch := make(chan AsyncResult[Transaction], 1)
	go this.withdrawBody(ch, code, amount, address, optionalArgs...)
	return ch
}
func (this *Tokocrypto) withdrawBody(ch chan AsyncResult[Transaction], code string, amount any, address any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	var tagWithdrawTag *string = nil
	tagWithdrawTag, paramsWithdrawTag := this.HandleParamString(params, "tag")
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	this.CheckAddress(address, code, tagWithdrawTag)
	var currency map[string]any = this.Currency(code)
	var request map[string]any = map[string]any{
		"asset":   currency["id"],
		"address": address,
		"amount":  this.NumberToString(amount),
	}
	if tagWithdrawTag != nil {
		request["addressTag"] = *tagWithdrawTag
	}
	networkCode, query := this.HandleNetworkCodeAndParams(paramsWithdrawTag)
	var networkId any = this.NetworkCodeToId(networkCode, code)
	if networkId != nil {
		request["network"] = ToUpper(networkId)
	}

	r1 := <-this.PrivatePostOpenV1Withdraws(this.Extend(request, query))
	if r1.Err != nil {
		panic(r1.Err)
	}
	var response map[string]any = r1.Value

	//
	//     {
	//         "code": 0,
	//         "msg": "成功",
	//         "data": {
	//             "withdrawId":"12"
	//         },
	//         "timestamp": 1571745049095
	//     }
	//
	ch <- AsyncResult[Transaction]{Value: this.ParseTransaction(response, currency)}
	return nil
}
func (this *Tokocrypto) Sign(path string, optionalArgs ...any) map[string]any {
	var api []string = GetArgStringSlice(optionalArgs, 0, []string{"public"})
	_ = api
	var method string = GetArgString(optionalArgs, 1, "GET")
	_ = method
	params := GetArg(optionalArgs, 2, map[string]any{})
	_ = params
	var apiName string = api[0]
	var restUrls map[string]any = this.Extend(map[string]any{}, this.UrlsApi["rest"])
	if _, ok := restUrls[apiName]; !ok {
		panic(NotSupported(this.Id + " does not have a testnet/sandbox URL for " + apiName + " endpoints"))
	}
	var baseApiUrl *string = this.SafeString(this.UrlsApi["rest"], apiName)
	if baseApiUrl == nil {
		panic(ExchangeError(this.Id + " sign() has no API URL for this endpoint"))
	}
	var url string = *baseApiUrl + "/" + path
	if apiName == "wapi" {
		url += ".html"
	}
	var userDataStream bool = (path == "userDataStream") || (path == "listenKey")
	if userDataStream {
		if this.ApiKey != "" {
			// v1 special case for userDataStream
			var headersStream map[string]any = map[string]any{
				"X-MBX-APIKEY": this.ApiKey,
				"Content-Type": "application/x-www-form-urlencoded",
			}
			var bodyStream *string = func() *string {
				if method != "GET" {
					return SafeStringPtr(this.Urlencode(params))
				}
				return nil
			}()
			return map[string]any{
				"url":     url,
				"method":  method,
				"body":    bodyStream,
				"headers": headersStream,
			}
		} else {
			panic(AuthenticationError(this.Id + " userDataStream endpoint requires `apiKey` credential"))
		}
	} else if (apiName == "private") || ((apiName == "sapi") && (path != "system/status")) || (apiName == "sapiV3") || ((apiName == "wapi") && (path != "systemStatus")) || (apiName == "dapiPrivate") || (apiName == "dapiPrivateV2") || (apiName == "fapiPrivate") || (apiName == "fapiPrivateV2") {
		this.CheckRequiredCredentials()
		var query string = ""
		var defaultRecvWindow *int64 = this.SafeInteger(this.Options, "recvWindow")
		var extendedParams map[string]any = this.Extend(map[string]any{
			"timestamp": this.Nonce(),
		}, params)
		if defaultRecvWindow != nil {
			extendedParams["recvWindow"] = defaultRecvWindow
		}
		var recvWindow *int64 = this.SafeInteger(params, "recvWindow")
		if recvWindow != nil {
			extendedParams["recvWindow"] = recvWindow
		}
		if (apiName == "sapi") && (path == "asset/dust") {
			query = this.UrlencodeWithArrayRepeat(extendedParams)
		} else if (path == "batchOrders") || (strings.Index(path, "sub-account") >= 0) || (path == "capital/withdraw/apply") || (strings.Index(path, "staking") >= 0) {
			query = this.Rawencode(extendedParams)
		} else {
			query = this.Urlencode(extendedParams)
		}
		var signature string = this.Hmac(this.Encode(query), this.Encode(this.Secret), sha256)
		query += "&" + "signature=" + signature
		var headersSigned map[string]any = map[string]any{
			"X-MBX-APIKEY": this.ApiKey,
		}
		var queryInUrl bool = (method == "GET") || (method == "DELETE") || (apiName == "wapi")
		var bodySigned *string = nil
		if queryInUrl {
			url += "?" + query
		} else {
			bodySigned = SafeStringPtr(query)
			headersSigned["Content-Type"] = "application/x-www-form-urlencoded"
		}
		return map[string]any{
			"url":     url,
			"method":  method,
			"body":    bodySigned,
			"headers": headersSigned,
		}
	} else {
		if paramsMap, _ := params.(map[string]any); len(paramsMap) > 0 {
			url += "?" + this.Urlencode(params)
		}
	}
	return map[string]any{
		"url":     url,
		"method":  method,
		"body":    nil,
		"headers": nil,
	}
}
func (this *Tokocrypto) HandleErrors(code int64, reason string, url string, method string, headers any, body string, response any, requestHeaders any, requestBody any) any {
	if (code == 418) || (code == 429) {
		panic(DDoSProtection(this.Id + " " + strconv.FormatInt(code, 10) + " " + reason + " " + body))
	}
	// error response in a form: { "code": -1013, "msg": "Invalid quantity." }
	// following block contains legacy checks against message patterns in "msg" property
	// will switch "code" checks eventually, when we know all of them
	if code >= 400 {
		if strings.Index(body, "Price * QTY is zero or less") >= 0 {
			panic(InvalidOrder(this.Id + " order cost = amount * price is zero or less " + body))
		}
		if strings.Index(body, "LOT_SIZE") >= 0 {
			panic(InvalidOrder(this.Id + " order amount should be evenly divisible by lot size " + body))
		}
		if strings.Index(body, "PRICE_FILTER") >= 0 {
			panic(InvalidOrder(this.Id + " order price is invalid, i.e. exceeds allowed price precision, exceeds min price or max price limits or is invalid value in general, use this.priceToPrecision (symbol, amount) " + body))
		}
	}
	if response == nil {
		return nil // fallback to default error handler
	}
	// check success value for wapi endpoints
	// response in format {'msg': 'The coin does not exist.', 'success': true/false}
	var success *bool = this.SafeBool(response, "success", true)
	var responseParsed any = response
	if !(success != nil && *success) {
		var messageInner *string = this.SafeString(response, "msg")
		if messageInner != nil {

			{
				func(this *Tokocrypto) (ret_ any) {
					defer func() {
						if e := recover(); e != nil {
							if e == "break" {
								return
							}
							ret_ = func(this *Tokocrypto) any {
								// catch block:
								// do nothing
								responseParsed = response
								return nil
							}(this)
						}
					}()
					// try block:
					responseParsed = JsonParse(messageInner)
					return nil
				}(this)

			}
		}
	}
	var message *string = this.SafeString(responseParsed, "msg")
	if message != nil {
		this.ThrowExactlyMatchedException(this.Exceptions["exact"], message, this.Id+" "+*message)
		this.ThrowBroadlyMatchedException(this.Exceptions["broad"], message, this.Id+" "+*message)
	}
	// checks against error codes
	var error *string = this.SafeString(responseParsed, "code")
	if error != nil {
		// https://github.com/ccxt/ccxt/issues/6501
		// https://github.com/ccxt/ccxt/issues/7742
		if (error != nil && *error == "200") || Precise.StringEquals(error, "0") {
			return nil
		}
		// a workaround for {"code":-2015,"msg":"Invalid API-key, IP, or permissions for action."}
		// despite that their message is very confusing, it is raised by Binance
		// on a temporary ban, the API key is valid, but disabled for a while
		if (error != nil && *error == "-2015") && (*this.SafeBool(this.Options, "hasAlreadyAuthenticatedSuccessfully", false)) {
			panic(DDoSProtection(this.Id + " " + body))
		}
		var feedback string = this.Id + " " + body
		if message != nil && *message == "No need to change margin type." {
			panic(MarginModeAlreadySet(feedback))
		}
		this.ThrowExactlyMatchedException(this.Exceptions["exact"], error, feedback)
		panic(ExchangeError(feedback))
	}
	if !(success != nil && *success) {
		panic(ExchangeError(this.Id + " " + body))
	}
	return nil
}
func (this *Tokocrypto) CalculateRateLimiterCost(api any, method string, path string, params any, optionalArgs ...any) any {
	var config map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = config
	var paramsDict map[string]any = this.Extend(map[string]any{}, params)
	var byLimit []any = SafeListTyped(config, "byLimit")
	if (func() bool { _, ok := paramsDict["noCoin"]; return ok }()) && !(func() bool { _, ok := paramsDict["coin"]; return ok }()) {
		return this.SafeInteger(config, "noCoin")
	} else if (func() bool { _, ok := paramsDict["noSymbol"]; return ok }()) && !(func() bool { _, ok := paramsDict["symbol"]; return ok }()) {
		return this.SafeInteger(config, "noSymbol")
	} else if (func() bool { _, ok := paramsDict["noPoolId"]; return ok }()) && !(func() bool { _, ok := paramsDict["poolId"]; return ok }()) {
		return this.SafeInteger(config, "noPoolId")
	} else if _, ok := paramsDict["limit"]; ok {
		var limit *int64 = this.SafeInteger(paramsDict, "limit")
		for i := 0; i < len(byLimit); i++ {
			var entry any = byLimit[i]
			var entryLimit *int64 = this.SafeInteger(entry, 0)
			if (limit != nil) && (entryLimit != nil) && (*limit <= *entryLimit) {
				return this.SafeInteger(entry, 1)
			}
		}
	}
	return this.SafeInteger(config, "cost", 1)
}

func NewTokocrypto(userConfig map[string]any) *Tokocrypto {
	p := newTokocrypto()
	p.Init(userConfig)
	return p
}

func (this *Tokocrypto) Init(userConfig map[string]any) {
	this.Exchange = Exchange{}
	this.Exchange.DerivedExchange = this
	this.Exchange.InitParent(userConfig, this.Describe(), this)
}

